<?php

namespace Database\Seeders;

use App\Models\Game;
use App\Models\Post;
use App\Models\PostCategory;
use Illuminate\Database\Seeder;

/**
 * Full article texts for the blog (SEO). Existing short posts get their full body only while they still
 * hold the original one-line stub, so edits made in the admin are never overwritten.
 * New posts are created as "pending_review": a person publishes them from the admin.
 */
class ArticleSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->articles() as $slug => $a) {
            $post = Post::where('slug', $slug)->first();
            $words = str_word_count(strip_tags($a['body'])) ?: count(preg_split('/\s+/u', trim(strip_tags($a['body']))));
            $data = [
                'body' => $a['body'],
                'seo_title' => $a['seo_title'],
                'seo_description' => $a['seo_description'],
                'read_minutes' => max(2, (int) ceil($words / 180)),
            ];
            if ($post) {
                $isStub = mb_strlen(strip_tags((string) $post->body)) < 300;
                if ($isStub) {
                    $post->fill($data + (isset($a['tags']) ? ['tags' => $a['tags']] : []))->save();
                }

                continue;
            }
            if (empty($a['new'])) {
                continue;
            }
            Post::create($data + [
                'slug' => $slug,
                'title' => $a['title'],
                'excerpt' => $a['excerpt'],
                'cover_image' => $a['cover'],
                'post_category_id' => PostCategory::where('slug', $a['category'])->value('id'),
                'game_id' => isset($a['game']) ? Game::where('slug', $a['game'])->value('id') : null,
                'tags' => $a['tags'] ?? [],
                'status' => 'pending_review',
                'created_by' => 'agent',
                'published_at' => now(),
            ]);
        }
    }

    protected function articles(): array
    {
        return [
